import React from 'react';

import Colors from '@dynatrace/strato-design-tokens/colors';
import { adjustFractionDigits, format, units } from '@dynatrace-sdk/units';

import type { DataTableV2AlignmentColumnDef } from './ColumnAlignment.js';
import type {
  ColorPalette,
  CustomColorPalette,
} from '../../../charts/core/types/color-palette.js';
import type { Timeseries } from '../../../charts/core/types/timeseries.js';
import { MultiMeterBarChart } from '../../../charts/meter-bar/multi-meter-bar/MultiMeterBarChart.js';
import { SIZE_8 } from '../../../charts/meter-bar/shared/types/default.js';
import { MeterBarChart } from '../../../charts/meter-bar/single-meter-bar/MeterBarChart.js';
import { Sparkline } from '../../../charts/sparkline/Sparkline.js';
import { _formatDate } from '../../../core/utils/create-datetime-default-formatter.js';
import { _convertToNumberIfPureNumber } from '../../../core/utils/string-utils.js';
import type {
  CellContext,
  ColumnDefBase,
  ColumnDefTemplate,
} from '../hooks/useTable/types.js';
import type { DataTableV2DisplayColumnDef } from '../public.api.js';

export type DataTableV2ColumnType =
  | 'text'
  | 'date'
  | 'bit'
  | 'number'
  | 'sparkline'
  | 'meterbar';

/**
 * Defined config options used in sparkline column
 */
export type DataTableV2SparklineColumnConfig = {
  color?: string;
  variant?: 'line' | 'area';
};

/**
 * Defined configuration options used in meterbar column.
 */
export type DataTableV2MeterbarColumnConfig = {
  color?: string;
  min?: number;
  max?: number;
  colorPalette?: ColorPalette | CustomColorPalette;
  showTooltip?: boolean;
  thresholds?: {
    value: number;
    color: string;
    name: string;
  }[];
};

/** Defines properties added to columns when useColumnTypes plugin hook is used. */
export type DataTableV2ColumnTypesColumnDef =
  | { columnType?: DataTableV2ColumnType; config?: never }
  | { columnType: 'meterbar'; config?: DataTableV2MeterbarColumnConfig }
  | {
      columnType: 'sparkline';
      config?: DataTableV2SparklineColumnConfig;
    };

/**
 * Function that sets the column alignment and the custom cell renderer
 * based on the column type from the column definition
 * @param column - column definition prop
 *
 * @returns the column alignment and the custom cell renderer based on the column type
 */
export function applyColumnTypes<TData, TValue>(
  column: DataTableV2DisplayColumnDef<TData, TValue>,
): {
  alignment?: DataTableV2AlignmentColumnDef['alignment'];
  cell?: ColumnDefBase<TData, TValue>['cell'];
} {
  if (column.columnType === undefined) {
    return {};
  }
  if (column.cell !== undefined) {
    return {};
  }

  if (column.columnType) {
    column.alignment = column.alignment
      ? column.alignment
      : getAlignmentBasedOnType(column.columnType);
    column.cell = getCellTypeRenderer(column.columnType) as ColumnDefTemplate<
      CellContext<TData, TValue>
    >;
  }

  return { alignment: column.alignment, cell: column.cell };
}

/** get text alignment of column based on columntype */
function getAlignmentBasedOnType(
  columnType: DataTableV2ColumnType,
): DataTableV2AlignmentColumnDef['alignment'] {
  switch (columnType) {
    case 'number':
    case 'bit':
    case 'date':
      return 'right';
    default:
      return 'left';
  }
}

/**
 * Typeguard function ensures that the defined config in the column definition contains certain properties.
 * @internal
 */
function isDatatableV2SparklineColumnConfig(
  config: unknown,
): config is DataTableV2SparklineColumnConfig {
  return (
    config !== null &&
    config !== undefined &&
    typeof config === 'object' &&
    ('color' in config || 'variant' in config)
  );
}

/**
 * Typeguard function ensures that the defined config in the column definition contains certain properties.
 * @internal
 */
function isDatatableVMeterbarColumnConfig(
  config: unknown,
): config is DataTableV2MeterbarColumnConfig {
  return (
    config !== null &&
    config !== undefined &&
    typeof config === 'object' &&
    ('colorPalette' in config ||
      'color' in config ||
      'threshold' in config ||
      'showTooltip' in config)
  );
}

const CELL_TYPE_RENDERERS: Record<
  string,
  ColumnDefBase<unknown, unknown>['cell']
> = {
  number: (props) => {
    const cellValue = props.getValue();
    if (typeof cellValue === 'string' || typeof cellValue === 'number') {
      const valueAsNumber =
        Number.isNaN(+cellValue) || cellValue === null
          ? ''
          : _convertToNumberIfPureNumber(cellValue as string);

      return typeof valueAsNumber === 'number'
        ? adjustFractionDigits(valueAsNumber)
        : '';
    }
  },
  bit: (props) => {
    const cellValue = props.getValue();
    if (typeof cellValue === 'string' || typeof cellValue === 'number') {
      const valueAsNumber = Number.isNaN(+cellValue)
        ? ''
        : _convertToNumberIfPureNumber(cellValue as string);

      return typeof valueAsNumber === 'number'
        ? format(cellValue as number, { input: units.data.bit })
        : '';
    }
  },
  date: (props) => {
    const cellValue = props.getValue();
    return (
      <>
        {_formatDate(
          new Date(_convertToNumberIfPureNumber(cellValue as string)),
        )}
      </>
    );
  },
  text: (props) => {
    const cellValue = props.getValue();
    return cellValue ? `${cellValue}` : '';
  },
  sparkline: (props) => {
    let config: DataTableV2SparklineColumnConfig = {};
    if (
      props.column.columnDef.meta &&
      isDatatableV2SparklineColumnConfig(props.column.columnDef.meta.config)
    ) {
      config = props.column.columnDef.meta.config;
    }

    return (
      <Sparkline
        data={props.getValue() as Timeseries[]}
        color={config?.color || Colors.Charts.Categorical.Color01.Default}
        variant={config?.variant || 'line'}
      ></Sparkline>
    );
  },
  meterbar: (props) => {
    let config: DataTableV2MeterbarColumnConfig = {};
    if (
      props.column.columnDef.meta &&
      isDatatableVMeterbarColumnConfig(props.column.columnDef.meta.config)
    ) {
      config = props.column.columnDef.meta.config;
    }
    return meterBarChart(props.getValue() as number, config);
  },
};

/**
 * Returns matching cell renderer for each of the different column types so
 * the values are displayed correctly.
 */
export function getCellTypeRenderer(columnType: DataTableV2ColumnType) {
  return CELL_TYPE_RENDERERS[columnType] ?? CELL_TYPE_RENDERERS.text;
}

/**
 * Function used for configuring and rendering the meterbar chart component
 */
function meterBarChart(
  value: number | { name: string; value: number; color?: string }[],
  config?: DataTableV2MeterbarColumnConfig,
): JSX.Element {
  // simple MeterBar
  if (typeof value === 'number') {
    return (
      <MeterBarChart
        value={value}
        min={config?.min}
        max={config?.max}
        color={config?.color as string}
        size={SIZE_8}
      >
        {config?.showTooltip && <MeterBarChart.Tooltip />}
        {config?.thresholds && (
          <MeterBarChart.Thresholds>
            {config?.thresholds?.map((threshold) => (
              <MeterBarChart.Threshold
                key={`threshold-${threshold.color}-${threshold.value}`}
                name={threshold.name}
                color={threshold.color}
                value={threshold.value}
              />
            ))}
          </MeterBarChart.Thresholds>
        )}
      </MeterBarChart>
    );
  } else {
    const isMultiMeterData =
      Array.isArray(value) &&
      value.every(
        (item) =>
          typeof item === 'object' &&
          typeof item.name === 'string' &&
          typeof item.value === 'number' &&
          (typeof item.color === 'undefined' || typeof item.color === 'string'),
      );
    if (!isMultiMeterData) {
      // eslint-disable-next-line no-console
      console.warn('Not valid meter chart data.');
    }

    // MultiMeterBar
    return (
      <MultiMeterBarChart
        size={'size8'}
        min={config?.min}
        max={config?.max}
        colorPalette={config?.colorPalette || 'categorical'}
      >
        {
          // only if this is multi meter data render segments
          isMultiMeterData &&
            value.map((data) => (
              <MultiMeterBarChart.Segment
                key={`${data.name}-${data.value}`}
                name={data.name}
                value={data.value}
                color={data?.color}
              />
            ))
        }
        <MeterBarChart.Tooltip />
        {config?.showTooltip && (
          <MultiMeterBarChart.Tooltip variant={'shared'} />
        )}
      </MultiMeterBarChart>
    );
  }
}
